mapper.select:
select 
from preg_report r
where r.del_flag = '0'

    and r.report_date >= #{from}


    and r.report_date <= #{to}


    and r.checkup_id = #{checkupId}

order by r.report_date desc, r.id desc

select r.report_date as recordDate, count(1) as total
from preg_report r
where r.report_date >= #{from}
  and r.report_date <= #{to}
  and r.del_flag = '0'
group by r.report_date
